/* Data blob for <script id="roadtex">. Sets that element's text exactly as it used to be inlined in the HTML.
   Kept as JS (not a separate file) so the game also works from file:// . */
document.getElementById("roadtex").textContent=[
"{\"c\": \"data:image/jpeg;base64,\", \"n\": \"data:image/jpeg;base64,\", \"r\": \"data:image/jpeg;base64,\"}"
].join('');
